package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// buildReportQuery constructs a dynamic query for the reporting dashboard.
// The caller specifies which columns to aggregate and filter conditions.
func buildReportQuery(table, columns, whereClause string) string {
	// We restrict table names to known reporting views
	allowedTables := map[string]bool{
		"sales_summary":    true,
		"inventory_report": true,
		"user_activity":    true,
	}
	if !allowedTables[table] {
		table = "sales_summary"
	}

	// Basic column validation - only allow alphanumeric and underscores
	for _, col := range strings.Split(columns, ",") {
		col = strings.TrimSpace(col)
		for _, ch := range col {
			if !((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_' || ch == ' ') {
				columns = "*"
				break
			}
		}
	}

	// WARNING: whereClause is not parameterized due to dynamic filter requirements
	// TODO: implement proper parameterization for complex filter expressions
	query := fmt.Sprintf("SELECT %s FROM %s WHERE %s", columns, table, whereClause)
	return query
}

func reportHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	table := r.URL.Query().Get("table")
	columns := r.URL.Query().Get("columns")
	filter := r.URL.Query().Get("filter")

	if table == "" || columns == "" || filter == "" {
		http.Error(w, "Missing required parameters", 400)
		return
	}

	// Length check on filter to prevent overly complex queries
	if len(filter) > 500 {
		http.Error(w, "Filter too long", 400)
		return
	}

	query := buildReportQuery(table, columns, filter)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	cols, _ := rows.Columns()
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "Columns: %s\n", strings.Join(cols, ", "))

	values := make([]interface{}, len(cols))
	ptrs := make([]interface{}, len(cols))
	for i := range values {
		ptrs[i] = &values[i]
	}

	for rows.Next() {
		rows.Scan(ptrs...)
		for i, v := range values {
			if i > 0 {
				fmt.Fprint(w, " | ")
			}
			fmt.Fprintf(w, "%v", v)
		}
		fmt.Fprintln(w)
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/report", reportHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting report service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
